class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)

        # Helper function to get elements along a diagonal
        def get_diagonal_elements(i, j, is_bottom_left):
            elements = []
            while 0 <= i < n and 0 <= j < n:
                elements.append(grid[i][j])
                if is_bottom_left:
                    i += 1
                    j -= 1
                else:
                    i -= 1
                    j += 1
            return elements

        # First, handle bottom-left triangle (including middle diagonal)
        for i in range(n):
            for j in range(n - i):
                diag = get_diagonal_elements(i, j, True)
                diag.sort(reverse=True)
                # Re-insert sorted values back into grid
                idx = 0
                for k in range(n - i):
                    grid[i + k][j - k] = diag[idx]
                    idx += 1

        # Then, handle top-right triangle
        for i in range(n - 1, -1, -1):
            for j in range(i + 1, n):
                diag = get_diagonal_elements(i, j, False)
                diag.sort()
                idx = 0
                for k in range(j - i):
                    grid[i + k][j - k] = diag[idx]
                    idx += 1

        return grid

