class Solution:
    def maxIncreasingSubarrays(self, nums: List[int]) -> int:
        if len(nums) < 2:
            return 0

        # Precompute the length of the longest strictly increasing subarray starting at each index
        n = len(nums)
        increasing = [1] * n

        for i in range(n - 2, -1, -1):
            if nums[i] < nums[i + 1]:
                increasing[i] = increasing[i + 1] + 1
            else:
                increasing[i] = 1

        # Now find the maximum k such that two adjacent subarrays of length k exist
        max_k = 0
        for i in range(n - 1):
            if increasing[i] >= 2 and increasing[i + 1] >= 2 and increasing[i] == increasing[i + 1]:
                max_k = max(max_k, increasing[i])

        return max_k

