class Solution:
    def lastMarkedNodes(self, edges: List[List[int]]) -> List[int]:
        # Build the adjacency list of the tree
        n = len(edges) + 1
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        # Function to compute the maximum depth from a starting node
        def bfs(start):
            visited = {start}
            queue = deque([(start, 0)])
            max_depth = 0
            farthest_node = start
            while queue:
                node, depth = queue.popleft()
                if depth > max_depth:
                    max_depth = depth
                    farthest_node = node
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        queue.append((neighbor, depth + 1))
            return farthest_node

        # For each node, compute the farthest node in the tree
        result = []
        for i in range(n):
            result.append(bfs(i))

