            is_sorted = all(subarray[j] < subarray[j + 1] for j in range(k - 1))
            if not is_sorted:
                result.append(-1)
                continue
            # Check if elements are consecutive
            max_val = max(subarray)
            if max_val - min(subarray) + 1 == k and set(subarray) == set(range(min(subarray), max_val + 1)):
                result.append(max_val)
            else:
                result.append(-1)

        return result

