import math
from functools import reduce

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        def gcd(a, b):
            return math.gcd(a, b)

        def lcm(a, b):
            return a * b // gcd(a, b)

        def compute_gcd(arr):
            return reduce(gcd, arr)

        def compute_lcm(arr):
            return reduce(lcm, arr)

        n = len(nums)
        max_score = 0

        # Case 1: Do not remove any element
        if n >= 1:
            current_gcd = compute_gcd(nums)
            current_lcm = compute_lcm(nums)
            max_score = current_gcd * current_lcm

        # Case 2: Remove one element
        for i in range(n):
            temp = nums[:i] + nums[i+1:]
            if len(temp) == 0:
                continue
            current_gcd = compute_gcd(temp)
            current_lcm = compute_lcm(temp)
            max_score = max(max_score, current_gcd * current_lcm)

        return max_score

