class Solution:
    def separateSquares(self, squares: List[List[int]]) -> float:
        # Collect all y-coordinates of square edges
        y_coords = set()
        for x, y, l in squares:
            y_coords.add(y)
            y_coords.add(y + l)

        # Convert to sorted list for binary search
        y_list = sorted(y_coords)

        # Binary search for the minimum y such that areas above and below are equal
        left, right = 0, len(y_list) - 1
        result = y_list[-1]  # default to highest y

        while left <= right:
            mid = (left + right) // 2
            y = y_list[mid]
            below_area = 0
            above_area = 0

            for x, y_sq, l in squares:
                if y_sq + l <= y:
                    below_area += l * l
                elif y_sq <= y:
                    # Partial overlap, compute the portion below y
                    height_below = y - y_sq
                    below_area += height_below * l
                else:
                    # Above y, compute portion above
                    height_above = y_sq + l - y
                    above_area += height_above * l

            if below_area == above_area:
                result = y
                right = mid - 1
            elif below_area < above_area:
                left = mid + 1
            else:
                right = mid - 1

        return round(result, 5)

